  function read() { try { const saved=JSON.parse(localStorage.getItem(key)||'{}'); return { profileId:saved.profileId||'', carts:saved.carts||{}, orders:saved.orders||{}, wishes:saved.wishes||{}, gifts:saved.gifts||{}, companion:saved.companion||{}, payers:saved.payers||{}, privateModes:saved.privateModes||{}, adultConfirmed:!!saved.adultConfirmed, catalogue:Array.isArray(saved.catalogue)?saved.catalogue:[], privateCatalogue:Array.isArray(saved.privateCatalogue)?saved.privateCatalogue:[], takeawayCatalogue:Array.isArray(saved.takeawayCatalogue)?saved.takeawayCatalogue:[], productArchive:Array.isArray(saved.productArchive)?saved.productArchive:[] }; } catch { return { profileId:'', carts:{}, orders:{}, wishes:{}, gifts:{}, companion:{}, payers:{}, privateModes:{}, adultConfirmed:false, catalogue:[], privateCatalogue:[], takeawayCatalogue:[], productArchive:[] }; } }
