  function product(id) { return catalogue.find(item=>item.id===id)||privateCatalogue.find(item=>item.id===id)||takeawayCatalogue.find(item=>item.id===id)||(state.productArchive||[]).find(item=>item.id===id)||legacyCatalogue.find(item=>item.id===id); }
