  function productCard(item) { const wished=items('wishes').some(entry=>entry.productId===item.id);const takeawayInfo=item.takeaway?productMeta(item):null;const image=productImage(item);const cover=image?`<img src="${esc(image)}" alt="${esc(item.name)}" loading="lazy">`:`<i>${esc(item.name.slice(0,1))}</i>`;return `<article class="shop-product ${item.takeaway?'is-takeaway':''}"><button class="shop-product-cover ${item.tone}" data-shop-product="${item.id}" type="button">${cover}</button><div><b>${esc(item.name)}</b><small>${esc(item.note)}</small>${takeawayInfo?`<em class="shop-takeaway-meta">${esc(takeawayInfo.distance)} · ${esc(takeawayInfo.deliveryTime)}</em>`:''}<span>¥ ${item.price}</span></div><button class="shop-wish ${wished?'is-active':''}" data-shop-wish="${item.id}" type="button">${icon('heart')}</button></article>`; }
