      orders: '<path d="M8 4.25H6.75a2 2 0 0 0-2 2v12.5a2 2 0 0 0 2 2h10.5a2 2 0 0 0 2-2V6.25a2 2 0 0 0-2-2H16"/><rect x="8" y="3" width="8" height="3.5" rx="1.25"/><path d="M8.5 11h7M8.5 15h4.5"/>',
