    return `<nav class="shop-tabs" aria-label="购物导航">${entries.map(([id,label])=>`<button class="${tab===id?'is-active':''}" data-shop-tab="${id}" type="button" aria-label="${label}${id==='cart'&&cartCount()?`，${cartCount()}件商品`:''}" ${tab===id?'aria-current="page"':''}>${dockIcon(id)}<small>${label}${id==='cart'&&cartCount()?` · ${cartCount()}`:''}</small></button>`).join('')}</nav>`;
