  function syncPendingPayments() {
    const chats=chatData().chats;let changed=false;const now=Date.now();
    for(const row of items('orders')) {
      if(orderStatus(row)!=='pending'||!row.paymentRequestId)continue;
      const messages=chats[row.paidByRole]?.messages||[];
      const paid=messages.find(message=>(message.id===row.paymentRequestId||message.shoppingReceiptFor===row.paymentRequestId)&&message.shoppingPaymentStatus==='paid');
      if(paid){const paidAt=Number(paid.shoppingPaidAt||paid.createdAt||now);row.status='ordered';row.shipAt=paidAt+Number(row.shippingDelayMs||0);row.arrivalAt=paidAt+Number(row.arrivalDelayMs||0);changed=true;}
    }
    for(const row of items('orders')) {
      if(!row.shipAt||orderStatus(row)==='pending'||orderStatus(row)==='received')continue;
      if(now>=Number(row.arrivalAt||Infinity)){row.status='received';row.shippedAt=Number(row.shipAt);row.deliveredAt=Number(row.arrivalAt);changed=true;}
      else if(now>=Number(row.shipAt)&&orderStatus(row)==='ordered'){row.status='shipping';row.shippedAt=Number(row.shipAt);changed=true;}
    }
    if(changed)save();
    return changed;
  }
