    const stall=flowerStalls.find(item=>item.id===stallId)||flowerStalls[0];
    const role=roles().find(item=>item.id===state.companion[state.profileId]);const p=profile();
    const config=window.IdealMachineAPI?.getConfig?.();const model=window.IdealMachineAPI?.getModel?.('shopping')||config?.models?.[0];
